StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Mechanical Filter Data - Aquaservice
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
// REQ: 			Aquaservice - Aquafilter Disk - ModbusTCP option                                                                                                                                                                                                                                                                                                                          
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-07-22		William Veim			Initial release              
//
//===============================================================================================================================

 (*************************************************************************
 *	CONGIURING MODBUS REQUEST
 *************************************************************************)
 
MTCP_Request[0].Enable :=										TRUE;
MTCP_Request[0].NodeAdr := 								1;
MTCP_Request[0].FunctionCode := 						eFun#Fn15_WriteMultipleCoils;
MTCP_Request[0].Write.StartAddressLocal :=			0;
MTCP_Request[0].Write.StartAddressRemote := 	0;
MTCP_Request[0].Write.Count := 							1;

MTCP_Request[1].Enable :=										TRUE;
MTCP_Request[1].NodeAdr := 								1;
MTCP_Request[1].FunctionCode := 						eFun#Fn01_ReadCoils;
MTCP_Request[1].Read.StartAddressLocal := 	 		2;
MTCP_Request[1].Read.StartAddressRemote :=  	3;
MTCP_Request[1].Read.Count := 						  	11;

MTCP_Request[2].Enable :=									 	TRUE;
MTCP_Request[2].NodeAdr := 							 	1;
MTCP_Request[2].FunctionCode := 					  	eFun#Fn03_ReadHoldingRegisters;
MTCP_Request[2].Read.StartAddressLocal := 	  		0;
MTCP_Request[2].Read.StartAddressRemote :=   	1;
MTCP_Request[2].Read.Count := 						   	10; 

FB_MTCP(Enable:=						TRUE, 
				IPAddress:=					Cfg_IPAdr, 
				PortNo:=						Cfg_PortNo, 
				UpdateRate:=				Cfg_UpdateRate, 
				NodeTimeOut:=			ADD_TIME(In1:=Cfg_UpdateRate, In2:=Cfg_UpdateRate), 
				Status=>						MTCP_Status, 
				RequestCycleDone=>	MTCP_ReqCycleDone, 
				RequestCycleTime=>	MTCP_ReqCycleTime, 
				Error=>						MTCP_Error, 
				ErrorID=>					MTCP_ErrorID, 
				ErrorIDEx=>					MTCP_ErrorID_Ex, 
				ErrorRequestNO=>		MTCP_ErrorRequestNO, 
				ModbusError=>			MTCP_ModbusError, 
				Requests:=					MTCP_Request, 
				Coils:=							MTCP_Coils, 
				DiscreteInputs:=			MTCP_DiscreteInputs, 
				InputRegisters:=			MTCP_InputRegister, 
				HoldingRegisters:=		MTCP_HoldingRegister);

(*************************************************************************
 *	INTERNAL VARIABLE CONTROL
 *************************************************************************)
 
Ext_MechanicalFilter_Data.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

FB_Watchdog(ENS:=TRUE, 
						Cfg_Type:=1,
						Inp_Bool:=TestABit(In:=MTCP_HoldingRegister[0], Pos:=14));

//Communication state
IF MTCP_Request[0].Status.Success AND NOT MTCP_Request[0].Status.Error 
	AND MTCP_Request[1].Status.Success AND NOT MTCP_Request[1].Status.Error
	AND MTCP_Request[2].Status.Success AND NOT MTCP_Request[2].Status.Error 
	AND NOT FB_Watchdog.Sts_Timeout THEN
	
	Wrk_CommState:=TRUE;
ELSE
	Wrk_CommState:=FALSE;
END_IF;

(*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)
 
IF NOT Wrk_CommState THEN
	Ext_MechanicalFilter_Data.EXT_Operator.Actual_State:= 'Communication fault';
ELSIF MTCP_Coils[12] THEN
	Ext_MechanicalFilter_Data.EXT_Operator.Actual_State:= 'Standby';
ELSIF MTCP_Coils[8] THEN
	Ext_MechanicalFilter_Data.EXT_Operator.Actual_State:= 'Flushing ongoing';
END_IF;

//Input data
Ext_MechanicalFilter_Data.EXT_Operator.FlushingStarted:= 			MTCP_Coils[8];
Ext_MechanicalFilter_Data.EXT_Operator.InletPressure:=			  	HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[0], UnvalidValue:=16#FFFF) / 100; 	// bar
Ext_MechanicalFilter_Data.EXT_Operator.OutletPressure:=			HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[1], UnvalidValue:=16#FFFF) / 100; 	// bar
Ext_MechanicalFilter_Data.EXT_Operator.DifferencialPressure:= 	HE_WORD_CheckValid(Word_1:=MTCP_HoldingRegister[2], UnvalidValue:=16#FFFF) / 100; 	// bar

//Output data
MTCP_Coils[0] :=Ext_MechanicalFilter_Data.EXT_Operator.ResetFault; //Fault acknowledge
MTCP_Coils[1] :=Ext_MechanicalFilter_Data.EXT_Operator.StartFlushing; //Fault acknowledge

(*************************************************************************
 *	STATISTICS
 *************************************************************************)
 
 RE_Flushing(Clk:=MTCP_Coils[8]);

IF RE_Flushing.Q THEN
	Ext_MechanicalFilter_Data.EXT_Statistics.Total_Today:=			Ext_MechanicalFilter_Data.EXT_Statistics.Total_Today + 1;
	Ext_MechanicalFilter_Data.EXT_Statistics.Total_Yesterday:=	Ext_MechanicalFilter_Data.EXT_Statistics.Total_Yesterday + 1;
	Ext_MechanicalFilter_Data.EXT_Statistics.Total_Week:=			Ext_MechanicalFilter_Data.EXT_Statistics.Total_Week + 1;	
	Ext_MechanicalFilter_Data.EXT_Statistics.Total_Month:=			Ext_MechanicalFilter_Data.EXT_Statistics.Total_Month + 1;
	Ext_MechanicalFilter_Data.EXT_Statistics.Total_Year:=				Ext_MechanicalFilter_Data.EXT_Statistics.Total_Year + 1;
	Ext_MechanicalFilter_Data.EXT_Statistics.Total:=						Ext_MechanicalFilter_Data.EXT_Statistics.Total + 1;
END_IF;

(*************************************************************************
 *	ALARM/FAULT STATUS
 *************************************************************************)

Wrk_State[1]:=NOT Wrk_CommState;
Wrk_Suffix[1]:='Communication fault';
Wrk_State[2]:=MTCP_Coils[2];
Wrk_Suffix[2]:='High differencial pressure';
Wrk_State[3]:=MTCP_Coils[3];
Wrk_Suffix[3]:='Limit switch closed fault';
Wrk_State[4]:=MTCP_Coils[4];
Wrk_Suffix[4]:='Limit switch open fault';
Wrk_State[5]:=MTCP_Coils[5];
Wrk_Suffix[5]:='Pressure sensor inlet fault';
Wrk_State[6]:=MTCP_Coils[6];
Wrk_Suffix[6]:='Pressure sensor outlet fault';
Wrk_State[7]:=MTCP_Coils[7];
Wrk_Suffix[7]:='Clogged filter';
Wrk_State[8]:=FALSE;
Wrk_Suffix[8]:='';
Wrk_State[9]:=FALSE;
Wrk_Suffix[9]:='';
Wrk_State[10]:=FALSE;
Wrk_Suffix[10]:='Service';
Wrk_State[11]:=FALSE;
Wrk_Suffix[11]:='';
Wrk_State[12]:=FALSE;
Wrk_Suffix[12]:='';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_Data_Logic(Ext_Alarm:=						Ext_MechanicalFilter_Data.EXT_Alarm, 
						EXT_Engineering:=			Ext_MechanicalFilter_Data.EXT_Engineering, 
						Ext_General:=					Ext_MechanicalFilter_Data.EXT_General, 
						Int_Alarm:=						Int_Alarm, 
						Inp_StateState:=				Wrk_State, 
						Inp_StateSuffix:=				Wrk_Suffix, 
						Inp_AlmSuppressDesc:=	Cfg_AlmSuppressDesc, 
						Inp_AlmSuppress:=			Inp_AlmSuppress);

(*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
 
 //BLOCK
 Sts_Alarm:= FB_Data_Logic.Sts_AlarmTriggered;
 
 //STRUCTURE
 Ext_MechanicalFilter_Data.EXT_General.Connected_ControlCabinet:=	Cfg_ConnCab;
 Ext_MechanicalFilter_Data.EXT_General.Controlled_FromController:=	Cfg_ControllerName;
 Ext_MechanicalFilter_Data.EXT_General.Process_TAG:=							Cfg_ProcessTAG;
